/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>boolean</returns>
protected boolean mayJournalBePosted(Common _salesTable)
{
    SalesTable localSalesTable = _salesTable as SalesTable;
    boolean checkCRLOK = true;
    boolean ok = next mayJournalBePosted(_salesTable);

    if (ok && !localSalesTable.InterCompanyDirectDelivery)
    {
        if (custParameters::find().salesCheckCreditOnHeader())
        {
            //localSalesTable.checkAgainstCreditLimit();
            CustCreditLimit custCreditLimit = CustCreditLimit::construct(localSalesTable, null);

            checkCRLOK = custCreditLimit.check();
        }
        if (!checkCRLOK)
        {
            if (Box::yesNo(strFmt("@NDX:NXACRLCheck", localSalesTable.SalesId), DialogButton::Yes) == DialogButton::No)
            {
                ok = false;
                throw error("@NDX:NDXEmptyEntry");
            }
        }
    }

    return ok;
}
